import { h } from 'preact';
import { loadPlanningPages } from './planning-data.js';
import { useEffect, useRef, useState } from 'preact/hooks';
import { Page, Field, Button, Notice, Empty, Loading, useLoad } from '../../components/ui.jsx';
import { formatBytes, uploadProgress, validateUpload, uploadAttachment } from './attachment-state.js';
export function AttachmentsPanel({ api, issueId }) {
  const attachments = useLoad(() => loadPlanningPages(api, '/issues/' + issueId + '/attachments'), [issueId]);
  const access = useLoad(async () => {
    const { issue } = await api.get('/issues/' + issueId);
    const project = await api.get('/projects/' + issue.projectId);
    return { write: project.permissions.write && !project.project.archived };
  }, [issueId]);
  const [file, setFile] = useState(null), [error, setError] = useState(null);
  const [notice, setNotice] = useState(''), [busy, setBusy] = useState(false);
  const [progress, setProgress] = useState(null);
  const controller = useRef(null), input = useRef(null);
  useEffect(() => () => controller.current?.abort(), [issueId]);
  async function upload(event) {
    event.preventDefault();
    const problem = validateUpload(file, attachments.data?.maxUploadBytes ?? 0);
    if (problem) { setError(new Error(problem)); return; }
    setError(null); setNotice(''); setBusy(true); setProgress({ loaded: 0, total: file.size });
    controller.current = new AbortController();
    try {
      const result = await uploadAttachment({ issueId, file, onProgress: setProgress, signal: controller.current.signal });
      setNotice(result.attachment.name + ' uploaded: ' + formatBytes(result.attachment.size) + ', SHA-256 ' + result.attachment.sha256);
      setFile(null); if (input.current) input.current.value = ''; attachments.reload();
    } catch (error) { setError(error); attachments.reload(); }
    finally { setBusy(false); controller.current = null; }
  }
  async function remove(attachment) {
    if (!globalThis.confirm('Delete attachment ' + attachment.name + '?')) return;
    setError(null); setBusy(true); setNotice('');
    try { await api.delete('/attachments/' + attachment.id); setNotice('Attachment deleted'); attachments.reload(); }
    catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  return <section className="panel attachments-panel"><h2>Attachments</h2>
    <Notice error={error ?? attachments.error ?? access.error} /><Notice>{notice}</Notice>
    {attachments.loading ? <Loading /> : !attachments.data?.items.length ? <Empty>No attachments yet.</Empty> : <ul className="attachments-list">
      {attachments.data.items.map(attachment => <li key={attachment.id}>
        <div><a href={attachment.downloadUrl} download={attachment.name}>{attachment.name}</a>
          <p>{formatBytes(attachment.size)} · {attachment.mediaType} · {new Date(attachment.createdAt).toLocaleString()}</p>
          <details><summary>SHA-256 integrity digest</summary><code className="digest">{attachment.sha256}</code></details>
        </div>
        {access.data?.write && <Button busy={busy} onClick={() => remove(attachment)}>Delete</Button>}
      </li>)}
    </ul>}
    {access.data?.write && <form onSubmit={upload}>
      <p>Maximum upload: {formatBytes(attachments.data?.maxUploadBytes ?? 0)}. Bytes are streamed, stored privately, and hashed by the server.</p>
      <Field label="Attachment file"><input type="file" ref={input} disabled={busy} onChange={event => setFile(event.currentTarget.files[0] ?? null)} /></Field>
      {file && <p>{file.name} · {formatBytes(file.size)}</p>}
      {progress && <div role="status"><progress max="100" value={uploadProgress(progress.loaded, progress.total)} aria-label="Attachment upload progress" /> {uploadProgress(progress.loaded, progress.total)}% · {formatBytes(progress.loaded)} sent</div>}
      <Button busy={busy} disabled={!file || attachments.loading} type="submit">Upload attachment</Button>
      {busy && <Button type="button" onClick={() => controller.current?.abort()}>Cancel upload</Button>}
    </form>}
  </section>;
}
export function IssueAttachmentsPage({ api, params }) {
  const result = useLoad(() => api.get('/issues/' + params.issueId), [params.issueId]);
  return <Page title={result.data ? result.data.issue.key + ' attachments' : 'Issue attachments'}>
    <Notice error={result.error} />
    <a href={'#/issues/' + params.issueId}>Back to issue</a>
    <AttachmentsPanel api={api} issueId={params.issueId} />
  </Page>;
}

export function toggleSelection(selected, issueId) {
  const next = new Set(selected);
  if (next.has(issueId)) next.delete(issueId);
  else next.add(issueId);
  return next;
}
export function destinationAt(document, x, y) {
  const target = document.elementFromPoint(x, y);
  const column = target?.closest('[data-status-id]');
  if (!column) return null;
  const card = target.closest('[data-issue-id]');
  return { statusId: column.dataset.statusId, beforeId: card?.dataset.issueId };
}
export function moveBody(destination, issueId) {
  return {
    statusId: destination.statusId,
    ...(destination.beforeId && destination.beforeId !== issueId ? { beforeId: destination.beforeId } : {}),
    ...(destination.afterId && destination.afterId !== issueId ? { afterId: destination.afterId } : {})
  };
}
export function bulkChanges(values) {
  const changes = {};
  if (values.statusId) changes.statusId = values.statusId;
  if (values.assigneeId) changes.assigneeId = values.assigneeId === '__unassigned' ? null : values.assigneeId;
  if (values.labelsMode === 'replace') changes.labelIds = values.labelIds;
  return { changes, ...(values.labelsMode === 'add' ? { addLabelIds: values.labelIds } : {}), ...(values.labelsMode === 'remove' ? { removeLabelIds: values.labelIds } : {}) };
}

import { h } from 'preact';
import { loadPlanningPages } from './planning-data.js';
import { useEffect, useRef, useState } from 'preact/hooks';
import { Page, Field, Button, Notice, Empty, Loading, useLoad } from '../../components/ui.jsx';
import { ProjectLinks } from './projects.jsx';
import { toggleSelection, destinationAt, moveBody, bulkChanges } from './board-state.js';
export function BoardPage({ api, params }) {
  const projectId = params.projectId;
  const [query, setQuery] = useState('');
  const [assigneeFilter, setAssigneeFilter] = useState('');
  const board = useLoad(() => api.get('/projects/' + projectId + '/board?q=' + encodeURIComponent(query) + '&assigneeId=' + encodeURIComponent(assigneeFilter)), [projectId, query, assigneeFilter]);
  const labels = useLoad(() => loadPlanningPages(api, '/projects/' + projectId + '/labels'), [projectId]);
  const roster = useLoad(async () => {
    return loadPlanningPages(api, '/projects/' + projectId + '/assignees');
  }, [projectId]);
  const [selected, setSelected] = useState(new Set());
  const [error, setError] = useState(null);
  const [notice, setNotice] = useState('');
  const [busy, setBusy] = useState(false);
  const [draggingId, setDraggingId] = useState(null);
  const [targetStatus, setTargetStatus] = useState(null);
  const drag = useRef(null);
  const suppressClickUntil = useRef(0);
  const [bulkStatus, setBulkStatus] = useState('');
  const [bulkAssignee, setBulkAssignee] = useState('');
  const [bulkLabels, setBulkLabels] = useState([]);
  const [labelsMode, setLabelsMode] = useState('unchanged');
  const canWrite = board.data?.permissions.write && !board.data?.project.archived;
  async function persistMove(issueId, destination) {
    if (!destination || !canWrite) return;
    setBusy(true); setError(null); setNotice('');
    try {
      const result = await api.post('/issues/' + issueId + '/move', moveBody(destination, issueId));
      setNotice(result.issue.key + ' moved to ' + result.issue.statusName);
      board.reload();
    } catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  useEffect(() => {
    function pointerMove(event) {
      const current = drag.current;
      if (!current) return;
      if (Math.abs(event.clientX - current.x) + Math.abs(event.clientY - current.y) > 5) {
        current.moved = true;
        setDraggingId(current.issueId);
        setTargetStatus(destinationAt(document, event.clientX, event.clientY)?.statusId ?? null);
        event.preventDefault();
      }
    }
    function pointerUp(event) {
      const current = drag.current;
      drag.current = null;
      setDraggingId(null); setTargetStatus(null);
      if (current?.moved) {
        suppressClickUntil.current = Date.now() + 500;
        persistMove(current.issueId, destinationAt(document, event.clientX, event.clientY));
      }
    }
    window.addEventListener('pointermove', pointerMove, { passive: false });
    window.addEventListener('pointerup', pointerUp);
    return () => {
      window.removeEventListener('pointermove', pointerMove);
      window.removeEventListener('pointerup', pointerUp);
    };
  }, [canWrite, projectId]);
  async function bulkEdit(event) {
    event.preventDefault(); setBusy(true); setError(null); setNotice('');
    try {
      const body = bulkChanges({ statusId: bulkStatus, assigneeId: bulkAssignee, labelsMode, labelIds: bulkLabels });
      const result = await api.post('/projects/' + projectId + '/issues/bulk', { issueIds: [...selected], ...body });
      setNotice(result.count + ' issues updated'); setSelected(new Set()); board.reload();
    } catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  function beginPointer(event, issueId) {
    if (!canWrite || busy || event.button !== 0 || event.target.closest('input,button,select')) return;
    drag.current = { issueId, x: event.clientX, y: event.clientY, moved: false };
  }
  function startNative(event, issueId) {
    drag.current = null;
    event.dataTransfer.setData('text/plain', issueId);
    event.dataTransfer.effectAllowed = 'move';
    setDraggingId(issueId);
  }
  function nativeDrop(event, statusId) {
    event.preventDefault();
    const issueId = event.dataTransfer.getData('text/plain');
    const target = event.target.closest('[data-issue-id]');
    setDraggingId(null); setTargetStatus(null);
    if (issueId) persistMove(issueId, { statusId, beforeId: target?.dataset.issueId });
  }
  if (board.loading && !board.data) return <Loading />;
  if (board.error && !board.data) return <Notice error={board.error} />;
  const project = board.data.project;
  return <Page title={project.name + ' board'} actions={<a href={'#/projects/' + projectId + '/issues'}>Create or edit issues</a>}>
    <ProjectLinks projectId={projectId} />
    <Notice error={error ?? board.error} /><Notice>{notice}</Notice>
    {project.archived && <Notice>This project is archived. Restore it to move or edit work.</Notice>}
    <div className="filters">
      <Field label="Find issues"><input type="search" value={query} placeholder="Key or title" onInput={event => setQuery(event.currentTarget.value)} /></Field>
      <Field label="Assignee"><select value={assigneeFilter} onChange={event => setAssigneeFilter(event.currentTarget.value)}>
        <option value="">Everyone</option>{roster.data?.items.map(person => <option value={person.userId}>{person.name}</option>)}
      </select></Field>
      <span role="status">{selected.size} selected</span>
      {selected.size > 0 && <Button onClick={() => setSelected(new Set())}>Clear selection</Button>}
    </div>
    {canWrite && selected.size > 0 && <form className="bulk-editor panel" onSubmit={bulkEdit}>
      <h2>Bulk edit {selected.size} issues</h2>
      <Field label="Status"><select value={bulkStatus} onChange={event => setBulkStatus(event.currentTarget.value)}>
        <option value="">Keep status</option>{project.statuses.map(status => <option value={status.id}>{status.name}</option>)}
      </select></Field>
      <Field label="Assignee"><select value={bulkAssignee} onChange={event => setBulkAssignee(event.currentTarget.value)}>
        <option value="">Keep assignee</option><option value="__unassigned">Unassigned</option>
        {roster.data?.items.map(person => <option value={person.userId}>{person.name}</option>)}
      </select></Field>
      <Field label="Label action"><select value={labelsMode} onChange={event => setLabelsMode(event.currentTarget.value)}>
        <option value="unchanged">Keep labels</option><option value="replace">Replace labels</option><option value="add">Add labels</option><option value="remove">Remove labels</option>
      </select></Field>
      {labelsMode !== 'unchanged' && <Field label="Labels"><select multiple value={bulkLabels} onChange={event => setBulkLabels([...event.currentTarget.selectedOptions].map(option => option.value))}>
        {labels.data?.items.map(label => <option value={label.id}>{label.name}</option>)}
      </select></Field>}
      <Button busy={busy} type="submit">Apply to selected issues</Button>
    </form>}
    <p className="board-help">Drag a card into a column or onto another card to place it first. Keyboard users can use each card’s move menu. Select cards for an atomic bulk edit.</p>
    <div className="kanban" aria-busy={busy}>
      {board.data.columns.map(({ status, issues }) => <section key={status.id} data-status-id={status.id} data-testid={'board-column-' + status.id}
        className={'kanban-column ' + (targetStatus === status.id ? 'drop-target' : '')}
        onDragOver={event => { if (canWrite) { event.preventDefault(); setTargetStatus(status.id); } }}
        onDrop={event => nativeDrop(event, status.id)}>
        <header><h2>{status.name}</h2><span>{issues.length}</span></header>
        {issues.length === 0 && <Empty>Drop an issue here</Empty>}
        {issues.map((issue, index) => <article key={issue.id} data-issue-id={issue.id} data-testid={'board-card-' + issue.id}
          draggable={Boolean(canWrite)} onDragStart={event => startNative(event, issue.id)}
          onDragEnd={() => { setDraggingId(null); setTargetStatus(null); }}
          onPointerDown={event => beginPointer(event, issue.id)}
          className={'kanban-card ' + (draggingId === issue.id ? 'dragging' : '')}>
          <div className="card-top"><small>{issue.key}</small>{canWrite && <input type="checkbox" aria-label={'Select ' + issue.key} checked={selected.has(issue.id)} onChange={() => setSelected(toggleSelection(selected, issue.id))} />}</div>
          <a href={'#/issues/' + issue.id} onClick={event => { if (Date.now() < suppressClickUntil.current || draggingId) event.preventDefault(); }}>{issue.title}</a>
          <p>{issue.assignee?.name ?? 'Unassigned'}{issue.estimate != null ? ' · ' + issue.estimate + ' points' : ''}</p>
          <div className="issue-labels">{issue.labels.map(label => <span style={{ borderColor: label.color }}>{label.name}</span>)}</div>
          {issue.dueDate && <small>Due {issue.dueDate}</small>}
          {canWrite && <div className="card-order-actions">
            <Button disabled={busy || index === 0} aria-label={'Move ' + issue.key + ' earlier'} onClick={() => persistMove(issue.id, { statusId: status.id, beforeId: issues[index - 1].id })}>Move up</Button>
            <Button disabled={busy || index === issues.length - 1} aria-label={'Move ' + issue.key + ' later'} onClick={() => persistMove(issue.id, { statusId: status.id, afterId: issues[index + 1].id })}>Move down</Button>
          </div>}
          {canWrite && <Field label={'Move ' + issue.key}><select value={issue.statusId} disabled={busy} onChange={event => persistMove(issue.id, { statusId: event.currentTarget.value })}>
            {project.statuses.map(status => <option value={status.id}>{status.name}</option>)}
          </select></Field>}
        </article>)}
      </section>)}
    </div>
  </Page>;
}

export async function loadPlanningPages(api, route) {
  const [pathname, search = ''] = route.split('?');
  const query = new URLSearchParams(search);
  query.set('limit', '200');
  query.delete('cursor');
  const items = [], cursors = new Set();
  let metadata = {};
  for (;;) {
    const page = await api.get(pathname + '?' + query.toString());
    if (!Array.isArray(page.items)) throw new Error('The server returned an invalid planning list');
    items.push(...page.items);
    metadata = { ...page, items: undefined };
    if (!page.nextCursor) return { ...metadata, items, nextCursor: null };
    if (typeof page.nextCursor !== 'string' || cursors.has(page.nextCursor)) throw new Error('The server returned a repeated planning cursor');
    cursors.add(page.nextCursor);
    query.set('cursor', page.nextCursor);
  }
}

import { h } from 'preact';
import { loadPlanningPages } from './planning-data.js';
import { useState } from 'preact/hooks';
import { Page, Field, Button, Notice, Empty, Loading, DataTable, useLoad } from '../../components/ui.jsx';
import { workflowPayload, moveWorkflowStatus, updateWorkflowStatus } from './project-state.js';
export function ProjectLinks({ projectId }) {
  const base = '#/projects/' + encodeURIComponent(projectId);
  return <nav className="project-tabs" aria-label="Project navigation">
    <a href={base}>Overview</a>
    <a href={base + '/issues'}>Issues</a>
    <a href={base + '/board'}>Board</a>
    <a href={base + '/sprints'}>Sprints</a>
    <a href={base + '/settings'}>Settings</a>
  </nav>;
}
export function ProjectsPage({ api, navigate }) {
  const orgs = useLoad(() => loadPlanningPages(api, '/orgs'), []);
  const [orgId, setOrgId] = useState('');
  const [archived, setArchived] = useState(false);
  const [error, setError] = useState(null);
  const [busy, setBusy] = useState(false);
  const projects = useLoad(() => loadPlanningPages(api, '/projects?archived=' + String(archived) + (orgId ? '&orgId=' + orgId : '')), [orgId, archived]);
  async function create(event) {
    event.preventDefault();
    setError(null);
    setBusy(true);
    const values = Object.fromEntries(new FormData(event.currentTarget));
    try {
      const result = await api.post('/orgs/' + values.orgId + '/projects', {
        key: values.key, name: values.name, description: values.description
      });
      navigate('/projects/' + result.project.id);
    } catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  return <Page title="Projects">
    <p>Organize work with a project key, an ordered workflow, a board, and sprints.</p>
    <div className="filters">
      <Field label="Organization"><select value={orgId} onChange={event => setOrgId(event.currentTarget.value)}>
        <option value="">All my organizations</option>
        {orgs.data?.items.map(org => <option value={org.id}>{org.name}</option>)}
      </select></Field>
      <label><input type="checkbox" checked={archived} onChange={event => setArchived(event.currentTarget.checked)} /> Show archived projects</label>
    </div>
    <Notice error={projects.error} />
    {projects.loading ? <Loading /> : <DataTable items={projects.data?.items ?? []} columns={[
      { key: 'key', label: 'Key', render: project => <a href={'#/projects/' + project.id}>{project.key}</a> },
      { key: 'name', label: 'Project' },
      { key: 'description', label: 'Description' },
      { key: 'statuses', label: 'Workflow', render: project => project.statuses.map(status => status.name).join(' → ') }
    ]} empty="No projects match. Create a project below to begin." />}
    <section className="panel">
      <h2>Create a project</h2>
      <Notice error={error} />
      <form onSubmit={create}>
        <Field label="Organization"><select name="orgId" required defaultValue={orgId}>
          <option value="">Choose an organization</option>
          {orgs.data?.items.map(org => <option value={org.id}>{org.name}</option>)}
        </select></Field>
        <Field label="Project key" name="key" placeholder="TEAM" required minLength={2} maxLength={12} pattern="[A-Za-z][A-Za-z0-9]+" error={error?.details?.key} />
        <Field label="Project name" name="name" required maxLength={160} error={error?.details?.name} />
        <Field label="Description"><textarea name="description" rows={4} maxLength={20000} /></Field>
        <Button busy={busy} type="submit">Create project</Button>
      </form>
    </section>
  </Page>;
}
export function ProjectPage({ api, params }) {
  const result = useLoad(() => api.get('/projects/' + params.projectId), [params.projectId]);
  if (result.loading) return <Loading />;
  if (result.error) return <Notice error={result.error} />;
  const { project } = result.data;
  return <Page title={project.name} actions={<a href={'#/projects/' + project.id + '/issues'}>Open issues</a>}>
    <ProjectLinks projectId={project.id} />
    {project.archived && <Notice>This project is archived. Restore it in settings before planning new work.</Notice>}
    <p><strong>{project.key}</strong> · {project.description || 'No description yet.'}</p>
    <section className="panel"><h2>Workflow</h2><ol>
      {project.statuses.map(status => <li key={status.id}>{status.name} <small>({status.category})</small></li>)}
    </ol></section>
    <p><a href={'#/projects/' + project.id + '/board'}>Plan on the board</a> · <a href={'#/projects/' + project.id + '/sprints'}>Manage sprints</a></p>
  </Page>;
}
export function WorkflowEditor({ statuses, onChange }) {
  function update(index, field, value) {
    onChange(updateWorkflowStatus(statuses, index, field, value));
  }
  function move(index, offset) {
    onChange(moveWorkflowStatus(statuses, index, offset));
  }
  return <fieldset><legend>Ordered workflow</legend>
    <p>Every workflow needs a todo and a done status. Move issues before removing a status.</p>
    {statuses.map((status, index) => <div className="workflow-row" key={status.id ?? 'new-' + index}>
      <Field label={'Status ' + (index + 1)}><input value={status.name} required maxLength={80} onInput={event => update(index, 'name', event.currentTarget.value)} /></Field>
      <Field label="Category"><select value={status.category} onChange={event => update(index, 'category', event.currentTarget.value)}>
        <option value="todo">Todo</option><option value="active">Active</option><option value="done">Done</option>
      </select></Field>
      <Button type="button" disabled={index === 0} onClick={() => move(index, -1)} aria-label={'Move ' + status.name + ' earlier'}>↑</Button>
      <Button type="button" disabled={index === statuses.length - 1} onClick={() => move(index, 1)} aria-label={'Move ' + status.name + ' later'}>↓</Button>
      <Button type="button" disabled={statuses.length <= 2} onClick={() => onChange(statuses.filter((_, position) => position !== index))}>Remove</Button>
    </div>)}
    <Button type="button" onClick={() => onChange([...statuses, { name: '', category: 'active' }])}>Add status</Button>
  </fieldset>;
}
export function ProjectSettings({ api, params, navigate }) {
  const result = useLoad(() => api.get('/projects/' + params.projectId), [params.projectId]);
  const [statuses, setStatuses] = useState(null);
  const [error, setError] = useState(null);
  const [notice, setNotice] = useState('');
  const [busy, setBusy] = useState(false);
  async function save(event) {
    event.preventDefault();
    setError(null); setNotice(''); setBusy(true);
    const values = Object.fromEntries(new FormData(event.currentTarget));
    try {
      await api.patch('/projects/' + params.projectId, { key: values.key, name: values.name, description: values.description });
      setNotice('Project saved'); result.reload();
    } catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  async function saveWorkflow() {
    setError(null); setBusy(true);
    try {
      const values = workflowPayload(statuses ?? result.data.project.statuses);
      await api.put('/projects/' + params.projectId + '/workflow', { statuses: values });
      setStatuses(null); setNotice('Workflow saved'); result.reload();
    } catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  async function archive() {
    setBusy(true); setError(null);
    try { await api.patch('/projects/' + params.projectId, { archived: !result.data.project.archived }); result.reload(); }
    catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  async function remove() {
    if (!globalThis.confirm('Delete this project and all its work? This cannot be undone.')) return;
    setBusy(true); setError(null);
    try { await api.delete('/projects/' + params.projectId); navigate('/projects'); }
    catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  if (result.loading) return <Loading />;
  if (result.error) return <Notice error={result.error} />;
  const { project, permissions } = result.data;
  return <Page title={project.name + ' settings'}>
    <ProjectLinks projectId={project.id} />
    <Notice error={error} /><Notice>{notice}</Notice>
    {!permissions.manage ? <Notice>Project settings require an organization owner or administrator.</Notice> : <>
      <form onSubmit={save} className="panel">
        <Field label="Project key" name="key" defaultValue={project.key} required maxLength={12} />
        <Field label="Name" name="name" defaultValue={project.name} required maxLength={160} />
        <Field label="Description"><textarea name="description" defaultValue={project.description} rows={4} /></Field>
        <Button busy={busy} type="submit">Save project</Button>
      </form>
      <section className="panel"><WorkflowEditor statuses={statuses ?? project.statuses} onChange={setStatuses} />
        <Button busy={busy} onClick={saveWorkflow}>Save workflow</Button>
      </section>
      <section className="panel"><h2>Project lifecycle</h2>
        <Button busy={busy} onClick={archive}>{project.archived ? 'Restore project' : 'Archive project'}</Button>
        <Button busy={busy} className="danger" onClick={remove}>Delete project</Button>
      </section>
    </>}
  </Page>;
}

import { h } from 'preact';
import { loadPlanningPages } from './planning-data.js';
import { useState } from 'preact/hooks';
import { Page, Field, Button, Notice, Empty, Loading, DataTable, useLoad } from '../../components/ui.jsx';
import { ProjectLinks } from './projects.jsx';
import { scopePreview, completionPreview, chartPoints, chartPath } from './sprint-state.js';
export function BurndownChart({ data }) {
  const actual = chartPoints(data.days, 'remaining');
  const ideal = chartPoints(data.days, 'idealRemaining');
  return <section className="panel"><h2>Daily burndown</h2>
    <p>Remaining points follow issue status and estimate changes. Scope additions/removals are retained. Unestimated issues contribute to the issue count.</p>
    <svg viewBox="0 0 700 220" role="img" aria-label="Sprint burndown: actual remaining points and ideal trend" className="burndown-chart">
      <title>{data.sprint.name} burndown</title><desc>Solid green is actual remaining points; the dashed gray line is the starting-scope ideal. The daily data table follows.</desc>
      <path d="M35,15 L35,190 L680,190" fill="none" stroke="#8a9aa5" />
      <path d={chartPath(ideal)} fill="none" stroke="#8a9aa5" strokeDasharray="5 5" strokeWidth="2" />
      <path d={chartPath(actual)} fill="none" stroke="#267969" strokeWidth="3" />
      {actual.map(point => <circle cx={point.x} cy={point.y} r="3" fill="#267969"><title>{point.date}: {point.value} points</title></circle>)}
      <text x="35" y="212" fontSize="11">{data.days[0]?.date}</text>
      <text x="590" y="212" fontSize="11">{data.days.at(-1)?.date}</text>
    </svg>
    <details><summary>View daily data ({data.days.length} days)</summary><DataTable items={data.days} keyField="date" columns={[
      { key: 'date', label: 'Date' }, { key: 'scope', label: 'Scope points' },
      { key: 'remaining', label: 'Remaining points' }, { key: 'scopeIssues', label: 'Scope issues' },
      { key: 'remainingIssues', label: 'Unfinished issues' },
      { key: 'idealRemaining', label: 'Ideal', render: day => day.idealRemaining.toFixed(1) }
    ]} /></details>
  </section>;
}
export function SprintsPage({ api, params, navigate }) {
  const projectId = params.projectId;
  const project = useLoad(() => api.get('/projects/' + projectId), [projectId]);
  const [status, setStatus] = useState('');
  const result = useLoad(() => loadPlanningPages(api, '/projects/' + projectId + '/sprints' + (status ? '?status=' + status : '')), [projectId, status]);
  const [error, setError] = useState(null), [busy, setBusy] = useState(false);
  async function create(event) {
    event.preventDefault(); setBusy(true); setError(null);
    const body = Object.fromEntries(new FormData(event.currentTarget));
    try { const result = await api.post('/projects/' + projectId + '/sprints', body); navigate('/sprints/' + result.sprint.id); }
    catch (error) { setError(error); }
    finally { setBusy(false); }
  }
  return <Page title={(project.data?.project.name ?? 'Project') + ' sprints'}>
    <ProjectLinks projectId={projectId} />
    <Notice error={error ?? result.error ?? project.error} />
    <Field label="Sprint state"><select value={status} onChange={event => setStatus(event.currentTarget.value)}>
      <option value="">All states</option><option value="planned">Planned</option><option value="active">Active</option><option value="completed">Completed</option>
    </select></Field>
    {result.loading ? <Loading /> : <DataTable items={result.data?.items ?? []} columns={[
      { key: 'name', label: 'Sprint', render: sprint => <a href={'#/sprints/' + sprint.id}>{sprint.name}</a> },
      { key: 'status', label: 'State' }, { key: 'startDate', label: 'Start' }, { key: 'endDate', label: 'End' },
      { key: 'issueCount', label: 'Issues' }, { key: 'remainingPoints', label: 'Remaining points' }
    ]} empty="No sprints yet. Plan the next delivery cycle below." />}
    {project.data?.permissions.write && !project.data.project.archived && <form className="panel" onSubmit={create}>
      <h2>Plan a sprint</h2>
      <Field label="Name" name="name" required maxLength={160} error={error?.details?.name} />
      <Field label="Goal"><textarea name="goal" rows={3} maxLength={10000} placeholder="What will the team deliver?" /></Field>
      <div className="filters"><Field label="Start date" name="startDate" type="date" required error={error?.details?.startDate} />
        <Field label="End date" name="endDate" type="date" required error={error?.details?.endDate} /></div>
      <Button type="submit" busy={busy}>Create planned sprint</Button>
    </form>}
  </Page>;
}
export function SprintPage({ api, params, navigate }) {
  const sprintId = params.sprintId;
  const detail = useLoad(() => api.get('/sprints/' + sprintId), [sprintId]);
  const burndown = useLoad(() => api.get('/sprints/' + sprintId + '/burndown'), [sprintId, detail.data?.sprint.updatedAt]);
  const project = useLoad(async () => {
    const { sprint } = await api.get('/sprints/' + sprintId);
    return api.get('/projects/' + sprint.projectId);
  }, [sprintId]);
  const candidates = useLoad(async () => {
    const { sprint } = await api.get('/sprints/' + sprintId);
    const [issues, sprints] = await Promise.all([
      loadPlanningPages(api, '/projects/' + sprint.projectId + '/issues'),
      loadPlanningPages(api, '/projects/' + sprint.projectId + '/sprints?status=planned')
    ]);
    return { issues: issues.items, sprints: sprints.items };
  }, [sprintId, detail.data?.sprint.updatedAt]);
  const [selected, setSelected] = useState(new Set());
  const [carryOver, setCarryOver] = useState('');
  const [error, setError] = useState(null), [notice, setNotice] = useState(''), [busy, setBusy] = useState(false);
  async function action(path, body = {}, method = 'post') {
    setBusy(true); setError(null); setNotice('');
    try {
      const result = await api[method]('/sprints/' + sprintId + path, body);
      setNotice('Sprint updated'); setSelected(new Set()); detail.reload(); burndown.reload(); candidates.reload();
      return result;
    } catch (error) { setError(error); return null; }
    finally { setBusy(false); }
  }
  async function save(event) {
    event.preventDefault();
    await action('', Object.fromEntries(new FormData(event.currentTarget)), 'patch');
  }
  async function removeSprint() {
    if (!globalThis.confirm('Delete this planned sprint and its scope history?')) return;
    const result = await action('', undefined, 'delete');
    if (result) navigate('/projects/' + detail.data.sprint.projectId + '/sprints');
  }
  if (detail.loading && !detail.data) return <Loading />;
  if (detail.error) return <Notice error={detail.error} />;
  const { sprint, issues: scope } = detail.data;
  const canWrite = project.data?.permissions.write && !project.data.project.archived && sprint.status !== 'completed';
  const occupied = new Set(scope.map(item => item.issueId));
  const available = (candidates.data?.issues ?? []).filter(issue => !occupied.has(issue.id));
  const preview = scopePreview(available, selected);
  const completion = completionPreview(scope);
  return <Page title={sprint.name} actions={<a href={'#/projects/' + sprint.projectId + '/sprints'}>All sprints</a>}>
    <ProjectLinks projectId={sprint.projectId} />
    <Notice error={error ?? burndown.error ?? candidates.error} /><Notice>{notice}</Notice>
    <p><strong>{sprint.status}</strong> · {sprint.startDate} → {sprint.endDate}</p>
    <p>{sprint.goal || 'No sprint goal has been set.'}</p>
    <div className="sprint-totals"><span>{sprint.issueCount} issues</span><span>{sprint.scopePoints} scope points</span><span>{sprint.remainingPoints} points remaining</span><span>{sprint.remainingIssueCount} unfinished issues</span></div>
    {canWrite && <form className="panel" onSubmit={save}>
      <h2>Sprint details</h2>
      <Field label="Name" name="name" defaultValue={sprint.name} required />
      <Field label="Goal"><textarea name="goal" defaultValue={sprint.goal} rows={3} /></Field>
      <div className="filters"><Field label="Start" name="startDate" type="date" defaultValue={sprint.startDate} readOnly={sprint.status === 'active'} required />
        <Field label="End" name="endDate" type="date" defaultValue={sprint.endDate} required /></div>
      <Button busy={busy} type="submit">Save sprint</Button>
    </form>}
    <section className="panel"><h2>Sprint scope</h2>
      <DataTable items={scope} keyField="issueId" empty="No issues in this sprint." columns={[
        { key: 'key', label: 'Issue', render: item => item.issue ? <a href={'#/issues/' + item.issueId}>{item.key}</a> : item.key },
        { key: 'title', label: 'Title' }, { key: 'estimate', label: 'Points' },
        { key: 'done', label: 'Result', render: item => item.done ? 'Done' : 'Unfinished' },
        { key: 'remove', label: 'Scope action', render: item => canWrite ? <Button busy={busy} onClick={() => action('/issues/' + item.issueId, undefined, 'delete')}>Remove</Button> : 'Historical' }
      ]} />
      {canWrite && <>
        <h3>Add issues</h3>
        {candidates.loading ? <Loading /> : available.length === 0 ? <Empty>No other project issues are available.</Empty> : <div className="scope-picker">
          {available.map(issue => <label><input type="checkbox" checked={selected.has(issue.id)} onChange={event => {
            const next = new Set(selected); if (event.currentTarget.checked) next.add(issue.id); else next.delete(issue.id); setSelected(next);
          }} /> {issue.key} · {issue.title} · {issue.estimate ?? 0} points</label>)}
        </div>}
        <p role="status">Scope preview: add {preview.count} issues and {preview.points} points. Existing scope is retained.</p>
        <Button busy={busy} disabled={!preview.count} onClick={() => action('/issues', { issueIds: preview.issueIds })}>Add selected issues</Button>
      </>}
    </section>
    {burndown.data && <BurndownChart data={burndown.data} />}
    {canWrite && sprint.status === 'planned' && <section className="panel"><h2>Start sprint</h2>
      <p>Starting activates this sprint. The project may have one active sprint at a time.</p>
      <Button busy={busy} onClick={() => action('/start')}>Start sprint</Button>
      <Button busy={busy} className="danger" onClick={removeSprint}>Delete planned sprint</Button>
    </section>}
    {canWrite && sprint.status === 'active' && <section className="panel"><h2>Complete sprint</h2>
      <p>Completion preview: {completion.completedCount} completed issues ({completion.completedPoints} points), {completion.unfinishedCount} unfinished issues ({completion.unfinishedPoints} points).</p>
      <Field label="Carry unfinished work to"><select value={carryOver} onChange={event => setCarryOver(event.currentTarget.value)}>
        <option value="">Keep unfinished work in completed history</option>
        {candidates.data?.sprints.filter(item => item.id !== sprint.id).map(item => <option value={item.id}>{item.name} · {item.startDate}</option>)}
      </select></Field>
      <p>{carryOver ? completion.unfinishedCount + ' unfinished issues will be added to the selected planned sprint.' : 'No new sprint scope will be created.'} Completed sprint history stays fixed.</p>
      <Button busy={busy} onClick={() => action('/complete', carryOver ? { carryOverSprintId: carryOver } : {})}>Complete sprint</Button>
    </section>}
    {sprint.result && <section className="panel"><h2>Completion result</h2>
      <p>{sprint.result.completedIssueIds.length} completed · {sprint.result.unfinishedIssueIds.length} unfinished · {sprint.result.carriedIssueIds.length} carried over</p>
      {sprint.result.carryOverSprintId && <a href={'#/sprints/' + sprint.result.carryOverSprintId}>Open carry-over sprint</a>}
    </section>}
  </Page>;
}
